{
"id": "OW-1c",
"gates": false,
"resolved_under_delegation": {
"true": "2026-11-12",
"ledger": "Delegated resolution 2026-11-12 — OD-12",
"corrected_by": "Correction 2026-11-12 — to the delegated resolution of OD-12"
},
"title": "Is the render table stored, or rebuilt each time?",
"question": "Is the render table stored and rewritten when a specification or its sources change, or rebuilt in full each time the site is built?",
"why_yours": "A stored table is a second home for what the specifications and sources already say, and a rebuilt one is not a record.",
"context": "A stored render table is quick for the site to read. It goes stale when something it was built from changes, for example a source's verification status. The project's way of catching that is to record a hash of the inputs on each row and to check for drift, as it does for determinations.\n\nA rebuilt render table is always current and has no staleness, but the build has to run the conversion each time, and the result is a build product and not a record you can point to.\n\nYour 2026-08-27 ruling is that render surfaces are read from the database when rendered, and that no committed file is a render. No source states a preference between the options below.",
"blocks": "The renderer and the render table (T-5).",
"options": [
{
"key": "stored",
"label": "Stored, with an inputs hash and a drift check",
"effect": "The table is written by a verb, each row points at its specification and records a hash of its inputs, and a check reports any row whose inputs have changed."
},
{
"key": "rebuilt",
"label": "Rebuilt each time the site is built",
"effect": "The table is generated from the specifications and sources at build time and is not kept. It is always current, and there is nothing to go stale."
},
{
"key": "other",
"label": "Something else",
"effect": "Say what in the note."
}
],
"source": "Ruling OW-1 of 2026-10-29 (ledger); CLAUDE.md rule 5"
}
