// ---------- pages ----------
function homePage() {
  const t = Object.values(SCHEMA.tables);
  const keys = promptKeys(), open = keys.filter((k) => !ANSWERS[k]).length;
  const find = h("input", { type: "search", id: "find", placeholder: "Find a table or a word", "aria-label": "Find a table or a word" });
  const sections = [];
  const order = [...META.stage_order, "unmapped"];
  for (const st of order) {
    const here = t.filter((x) => (stageOf(x.name) || "unmapped") === st).sort((a, b) => a.name.localeCompare(b.name));
    if (!here.length) continue;
    sections.push(h("section", { class: "sec", "data-stage": st },
      h("h2", null, st + " · " + here.length + (here.length === 1 ? " table" : " tables")), h("div", { class: "stack" }, here.map(tableItem))));
  }
  find.addEventListener("input", () => {
    const needle = find.value.trim().toLowerCase();
    for (const a of document.querySelectorAll("#main a.item[data-find]")) a.hidden = !!needle && !a.dataset.find.includes(needle);
    for (const s of document.querySelectorAll("#main section[data-stage]")) s.hidden = ![...s.querySelectorAll("a.item")].some((a) => !a.hidden);
  });
  const views = Object.values(SCHEMA.views);
  const gs = META.gloss_status;
  return [
    h("div", { class: "stack" },
      h("h1", null, "Guidebook database"),
      h("p", { class: "gl" }, "A copy of the database, opened on this device. Tap a table to read its rows. Nothing you do here changes the database; the answers you save are kept on this page only.")),
    h("a", { class: "item", href: "#waiting" }, h("span", { class: "top" }, h("span", { class: "nm" }, "Waiting on you"), h("span", { class: "n" }, fmt(open))),
      h("span", { class: "gl" }, "Questions with the context to answer them: " + openDecisions().length + " decisions on the plan and " + (keys.length - openDecisions().length) + " rows in the database. " + (keys.length - open) + " answered on this page, and " + (META.decisions.length - openDecisions().length + queueRows().reduce((a, x) => a + x.ruled.length, 0)) + " already ruled in the ledger.")),
    find, sections,
    h("section", { class: "sec" }, h("h2", null, "Views · " + views.length),
      h("details", null, h("summary", null, "Saved queries that read the tables"), h("div", { class: "body" },
        views.map((v) => h("a", { class: "item", href: "#v-" + slug(v.name) },
          h("span", { class: "top" }, h("span", { class: "nm" }, v.name), h("span", { class: "n" }, fmt(v.rows))),
          h("span", { class: "gl" }, "reads " + (v.reads.join(", ") || "nothing"))))))),
    h("div", { class: "foot" },
